import math

def g(a):
    v1 = math.floor(22 * a)
    v2 = math.floor(22 * a * v1)
    v3 = math.floor(22 * a * v2)
    return v3

def check_a(a):
    return a * g(a)

def search_k(k_min, k_max):
    solutions = []
    for k in range(k_min, k_max + 1):
        if k == 0: continue
        a = 4/k
        if abs(check_a(a) - 4) < 1e-9:
            solutions.append(k)
    return solutions

print("k values that give a*g(a)=4:", search_k(-1000, 1000))
